#!/usr/bin/env python3
"""TaskBrigade data guard. Generated by tbr-admin; requires only Python 3 and Git."""
import re
import subprocess
import sys

BLOCKED_EXTENSIONS = ()  # Filled from attachments.BLOCKED_EXTENSIONS by the installer.


def git(*args):
    # Preserve GIT_OBJECT_DIRECTORY / GIT_ALTERNATE_OBJECT_DIRECTORIES: incoming objects
    # live in receive-pack's quarantine until every pre-receive hook accepts the push.
    return subprocess.check_output(["git", *args], stderr=subprocess.DEVNULL)


def check(stream):
    seen = set()
    for line in stream:
        old, new, ref = line.split()
        if not all(re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", sha) for sha in (old, new)):
            raise ValueError("invalid object id")
        if set(new) == {"0"}:  # Branch/tag deletion.
            continue
        # Peel annotated tags. Non-commit tags are refused: they could expose a raw blob.
        tip = git("rev-parse", "--verify", new + "^{commit}").strip().decode("ascii")
        args = ["rev-list", tip]
        if set(old) != {"0"}:
            args.append("^" + old)
        commits = [tip, *git(*args).decode("ascii").splitlines()]
        for commit in commits:
            if commit in seen:
                continue
            seen.add(commit)
            # Whole trees also cover merges, renames, and files added then removed in
            # intermediate commits. NUL delimiters handle arbitrary Git filenames.
            for path in git("ls-tree", "-r", "-z", "--name-only", commit).split(b"\0"):
                name = path.rsplit(b"/", 1)[-1]
                extension = name.rsplit(b".", 1)[-1].lower() if b"." in name else b""
                if extension in BLOCKED_EXTENSIONS:
                    print("TaskBrigade: push rejected: spreadsheet/archive file "
                          + repr(path.decode("utf-8", "backslashreplace"))
                          + " is forbidden in this data-zone repository. "
                          "Use the encrypted Data upload in TaskBrigade; remove the file "
                          "from every incoming commit before retrying.", file=sys.stderr)
                    return 1
    return 0


def main():
    try:
        return check(sys.stdin)
    except (OSError, ValueError, subprocess.SubprocessError):
        print("TaskBrigade: push rejected: data-zone guard could not inspect the push. "
              "Contact the Gitea administrator (non-commit tags are not supported).", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())
